<?php
class NewsPageObservedAccess extends NewsDataAccess{
 var $seen_posts=array();var $seen_articles=array();
 function fetchPosts($id,$start=0){$rows=parent::fetchPosts($id,$start);$this->seen_posts=array();foreach($rows as$r){$this->seen_posts[]=(int)$r['post_id'];}return$rows;}
 function fetchArticles($sort=0,$cat=0,$start=0){$rows=parent::fetchArticles($sort,$cat,$start);$this->seen_articles=array();foreach($rows as$r){$this->seen_articles[]=(int)$r['topic_id'];}return$rows;}
}
function ng_native_page($file,$config,$request,$topic=null,$override=0){
 global$nt_app;
 $_GET=$request;$n=ng_module($file,$config);$n->data=new NewsPageObservedAccess($nt_app);if($topic===null){$n->render();}else{$n->renderArticles($topic,$override);$n->renderPagination();}return$n;
}
