 }
 foreach(array(array(-1,0),array(1,0),array(3,2),array(999999999,4))as$v){$n=ng_native_page('news.tpl',array('news_item_num'=>2),array('start'=>$v[0]),100);nt_check($n->page_start===$v[1]&&$n->data->seen_posts===array_slice(array(5005,5004,5003,5002,5001),$v[1],2),'Requested comment offset resolves to a valid first/current/last page');$cases++;}
 $n=ng_native_page('news.tpl',array('news_item_num'=>2),array(),100,3);nt_check($n->page_size===3&&$n->data->seen_posts===array(5005,5004,5003),'Explicit component page size also governs comments and pager');$cases++;
 foreach(array(SORT_DATE_ASC,SORT_DATE_DEC,SORT_ALPH_ASC,SORT_ALPH_DEC)as$sort){$data=new NewsPageObservedAccess($nt_app);$data->setItemCount(2);$rows=array_merge($data->fetchArticles($sort,2,0),$data->fetchArticles($sort,2,2),$data->fetchArticles($sort,2,4));$ids=array();foreach($rows as$row){$ids[]=(int)$row['topic_id'];}$ascending=in_array($sort,array(SORT_DATE_ASC,SORT_ALPH_ASC),true);nt_check($ids===($ascending?array(2000,2001,2002,2003,2004):array(2004,2003,2002,2001,2000)),'Every supported equal-title/date ordering has a unique final key');$cases++;}
 foreach(array('english','german')as$locale){foreach(array('guest','member','admin')as$role){nt_context($locale,$role!=='guest');$userdata['user_id']=$role==='guest'?-1:($role==='admin'?9:8);$userdata['user_level']=$role==='admin'?ADMIN:USER;$tree=array();foreach(array('news.tpl','portal_body.tpl')as$file){
