  foreach(array(900,300,999999)as$topic){$n=ng_native_page($file,array('news_item_num'=>2),array('news_id'=>$topic),null);$html=nt_html($n->template);$allowed=$topic===900&&$role==='admin';nt_check(($allowed?count($n->template->_tpldata['articles.'])===1:!isset($n->template->_tpldata['articles.']))&&!isset($n->template->_tpldata['comments.'])&&!isset($n->template->_tpldata['pagination.'])&&strpos($html,'ORPHAN_MUST_NOT_LEAK')===false,'Missing, non-news and inaccessible parents cannot expose orphan comments or pager');$cases++;}
  $n=ng_native_page($file,array('news_item_num'=>1001),array('cat_id'=>1),0);nt_check($n->item_count===($role==='admin'?107:105),'Article count respects current forum ACLs and news category');$cases++;
 }nt_check(nn_snapshot()===$before,'Every complete native module/dispatcher/template pass leaves source data unchanged');}}
 foreach(array('comments','articles')as$kind){$db->failure=$kind==='comments'?'COUNT( t.topic_id ) AS news_count':'COUNT( t.topic_id ) AS a_count';$failed=false;try{ng_native_page('news.tpl',array('news_item_num'=>2),array(),$kind==='comments'?100:0);}catch(NewsReaderFailure$error){$failed=true;}finally{$db->failure='';}nt_check($failed&&!isset($GLOBALS['template']->_tpldata['comments.'])&&!isset($GLOBALS['template']->_tpldata['articles.']),'Count failures abort before partially rendering a page');$cases++;}
 nt_check(nn_snapshot()===$before,'Count failures preserve every canonical row');
 echo 'News pagination native: ',$cases,' cases, ',$nt_checks," assertions PASS; actual module/dispatcher/SQL/XS, complete comment/category/capped pages, deterministic ties, current ACLs/bylines/markers, valid offsets and unchanged data.\n";
